+package com.vaadinbench;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.ListItem;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.html.UnorderedList;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.Route;
+
+@Route(value = "", layout = MainLayout.class)
+public class MainView extends VerticalLayout {
+
+    private TextField itemField;
+    private Button addButton;
+    private Button clearButton;
+    private UnorderedList itemsList;
+    private Span itemCount;
+
+    public MainView() {
+        H1 heading = new H1("Items");
+
+        itemField = new TextField();
+        itemField.setLabel("Item");
+
+        addButton = new Button("Add", event -> addItem());
+        clearButton = new Button("Clear", event -> clearItems());
+
+        itemsList = new UnorderedList();
+        itemCount = new Span("Items: 0");
+
+        add(heading, itemField, addButton, clearButton, itemsList, itemCount);
+    }
+
+    private void addItem() {
+        String value = itemField.getValue().trim();
+
+        if (value.isEmpty()) {
+            itemField.setInvalid(true);
+            return;
+        }
+
+        itemField.setInvalid(false);
+        itemsList.add(new ListItem(value));
+        itemField.setValue("");
+        updateCount();
+    }
+
+    private void clearItems() {
+        itemsList.removeAll();
+        updateCount();
+    }
+
+    private void updateCount() {
+        int count = (int) itemsList.getChildren().count();
+        itemCount.setText("Items: " + count);
+    }
+}
